package com.database.societyproject.maintenancepayment.service;

import com.database.societyproject.common.exception.*;
import com.database.societyproject.finance.entity.PaymentMethod;
import com.database.societyproject.maintenancebilling.entity.MonthlyMaintenanceBill;
import com.database.societyproject.maintenancebilling.repository.MonthlyMaintenanceBillRepository;
import com.database.societyproject.maintenancebilling.service.MonthlyMaintenanceBillingService;
import com.database.societyproject.maintenancepayment.dto.*;
import com.database.societyproject.maintenancepayment.entity.*;
import com.database.societyproject.maintenancepayment.repository.*;
import com.database.societyproject.occupancy.entity.*;
import com.database.societyproject.occupancy.repository.FlatOccupancyRepository;
import com.database.societyproject.notification.service.NotificationService;
import com.database.societyproject.security.service.SocietyAuthorizationService;
import com.database.societyproject.user.entity.User;
import com.database.societyproject.user.repository.UserRepository;
import com.fasterxml.jackson.databind.*;
import java.math.*; import java.net.*; import java.net.http.*; import java.nio.charset.StandardCharsets; import java.time.*; import java.util.*; import javax.crypto.Mac; import javax.crypto.spec.SecretKeySpec;
import org.springframework.beans.factory.annotation.Value; import org.springframework.security.access.AccessDeniedException; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;

@Service @Transactional
public class MaintenancePaymentService {
 private final MaintenancePaymentRepository payments; private final MaintenancePaymentAllocationRepository allocations; private final MonthlyMaintenanceBillRepository bills; private final MonthlyMaintenanceBillingService billing; private final FlatOccupancyRepository occupancies; private final SocietyAuthorizationService authorization; private final UserRepository users; private final ObjectMapper mapper; private final NotificationService notifications; private final String keyId,keySecret,webhookSecret;
 public MaintenancePaymentService(MaintenancePaymentRepository payments,MaintenancePaymentAllocationRepository allocations,MonthlyMaintenanceBillRepository bills,MonthlyMaintenanceBillingService billing,FlatOccupancyRepository occupancies,SocietyAuthorizationService authorization,UserRepository users,ObjectMapper mapper,NotificationService notifications,@Value("${app.razorpay.key-id}") String keyId,@Value("${app.razorpay.key-secret}") String keySecret,@Value("${app.razorpay.webhook-secret}") String webhookSecret){this.payments=payments;this.allocations=allocations;this.bills=bills;this.billing=billing;this.occupancies=occupancies;this.authorization=authorization;this.users=users;this.mapper=mapper;this.notifications=notifications;this.keyId=keyId;this.keySecret=keySecret;this.webhookSecret=webhookSecret;}
 public OnlineOrderResponse createOnlineOrder(OnlineOrderRequest request){requireKeys(); List<Long> ids=request.billIds().stream().distinct().toList(); if(ids.size()!=request.billIds().size())throw new InvalidRequestException("Choose each bill only once"); billing.refreshOverdueBills(); List<MonthlyMaintenanceBill> selected=new ArrayList<>(); Long societyId=null; for(Long id:ids){MonthlyMaintenanceBill bill=lockedBill(id); requireOwner(bill); if(societyId==null)societyId=bill.getSociety().getId(); if(!societyId.equals(bill.getSociety().getId()))throw new InvalidRequestException("Selected bills must belong to one society"); selected.add(bill);} selected.sort(Comparator.comparing(MonthlyMaintenanceBill::getDueDate).thenComparing(MonthlyMaintenanceBill::getId)); BigDecimal total=selected.stream().map(this::outstanding).reduce(BigDecimal.ZERO,BigDecimal::add); if(total.signum()<=0)throw new InvalidRequestException("The selected bills are already paid"); MaintenancePayment payment=new MaintenancePayment(); payment.setSociety(selected.get(0).getSociety()); payment.setPayer(users.getReferenceById(authorization.currentUserId())); payment.setAmount(total); payment.setPaymentDate(LocalDate.now()); payment.setPaymentMethod(PaymentMethod.ONLINE); payment.setStatus(MaintenancePaymentStatus.CREATED); payments.save(payment); for(MonthlyMaintenanceBill bill:selected)saveAllocation(payment,bill,outstanding(bill)); long paise=total.movePointRight(2).longValueExact(); String orderId=createRazorpayOrder(paise,"maintenance_"+payment.getId()); payment.setRazorpayOrderId(orderId); return new OnlineOrderResponse(payment.getId(),orderId,paise,"INR",keyId); }
 public MaintenancePaymentResponse verify(OnlineVerificationRequest request){MaintenancePayment payment=findOrder(request.razorpayOrderId()); requireOwnerPayment(payment); if(payment.getStatus()==MaintenancePaymentStatus.COMPLETED)return response(payment); if(!constantTime(hmac(payment.getRazorpayOrderId()+"|"+request.razorpayPaymentId(),keySecret),request.razorpaySignature()))throw new InvalidRequestException("Razorpay payment signature is invalid"); return complete(payment,request.razorpayPaymentId());}
 public void webhook(String raw,String signature){requireWebhook(); if(!constantTime(hmac(raw,webhookSecret),signature))throw new InvalidRequestException("Razorpay webhook signature is invalid"); try{JsonNode root=mapper.readTree(raw); if(!"payment.captured".equals(root.path("event").asText()))return; JsonNode entity=root.path("payload").path("payment").path("entity"); String orderId=entity.path("order_id").asText();String paymentId=entity.path("id").asText();if(!orderId.isBlank()&&!paymentId.isBlank()){MaintenancePayment payment=findOrder(orderId);if(payment.getStatus()==MaintenancePaymentStatus.CREATED)complete(payment,paymentId);}}catch(InvalidRequestException e){throw e;}catch(Exception e){throw new InvalidRequestException("Invalid Razorpay webhook payload");}}
 public MaintenancePaymentResponse recordOffline(OfflinePaymentRequest request){if(request.paymentMethod()!=PaymentMethod.CASH&&request.paymentMethod()!=PaymentMethod.BANK_TRANSFER)throw new InvalidRequestException("Offline payments must be cash or bank transfer"); MonthlyMaintenanceBill bill=lockedBill(request.billId()); authorization.requireManager(bill.getSociety().getId()); billing.refreshBill(bill); if(request.amount().compareTo(outstanding(bill))>0)throw new InvalidRequestException("Offline payment cannot exceed the outstanding bill amount"); MaintenancePayment payment=new MaintenancePayment();payment.setSociety(bill.getSociety());payment.setPayer(ownerOf(bill));payment.setRecordedBy(users.getReferenceById(authorization.currentUserId()));payment.setAmount(request.amount());payment.setPaymentDate(request.paymentDate());payment.setPaymentMethod(request.paymentMethod());payment.setReferenceNumber(request.referenceNumber().trim());payment.setNotes(blank(request.notes()));payment.setStatus(MaintenancePaymentStatus.COMPLETED);payment.setCompletedAt(LocalDateTime.now());payments.save(payment);saveAllocation(payment,bill,request.amount());applyAllocation(bill,request.amount());notifications.notifyMaintenancePaymentCompleted(payment);return response(payment);}
 @Transactional(readOnly=true) public List<MaintenancePaymentResponse> bySociety(Long societyId){authorization.requireManager(societyId);return payments.findBySocietyIdOrderByCreatedAtDesc(societyId).stream().map(this::response).toList();}
 @Transactional(readOnly=true) public List<MaintenancePaymentResponse> mine(){return payments.findByPayerIdOrderByCreatedAtDesc(authorization.currentUserId()).stream().map(this::response).toList();}
 private MaintenancePaymentResponse complete(MaintenancePayment payment,String razorpayPaymentId){List<MaintenancePaymentAllocation> items=allocations.findByPaymentId(payment.getId()); for(MaintenancePaymentAllocation item:items){MonthlyMaintenanceBill bill=lockedBill(item.getBill().getId());billing.refreshBill(bill);if(item.getAmount().compareTo(outstanding(bill))>0){payment.setStatus(MaintenancePaymentStatus.REQUIRES_REVIEW);payment.setRazorpayPaymentId(razorpayPaymentId);return response(payment);}} for(MaintenancePaymentAllocation item:items){MonthlyMaintenanceBill bill=lockedBill(item.getBill().getId());applyAllocation(bill,item.getAmount());}payment.setStatus(MaintenancePaymentStatus.COMPLETED);payment.setRazorpayPaymentId(razorpayPaymentId);payment.setReferenceNumber(razorpayPaymentId);payment.setCompletedAt(LocalDateTime.now());notifications.notifyMaintenancePaymentCompleted(payment);return response(payment);}
 private void applyAllocation(MonthlyMaintenanceBill bill,BigDecimal amount){bill.setPaidAmount(bill.getPaidAmount().add(amount));billing.refreshBill(bill);}
 private void saveAllocation(MaintenancePayment payment,MonthlyMaintenanceBill bill,BigDecimal amount){MaintenancePaymentAllocation allocation=new MaintenancePaymentAllocation();allocation.setPayment(payment);allocation.setBill(bill);allocation.setAmount(amount);allocations.save(allocation);}
 private MonthlyMaintenanceBill lockedBill(Long id){return bills.findByIdForUpdate(id).orElseThrow(()->new ResourceNotFoundException("Monthly maintenance bill",id));}
 private void requireOwner(MonthlyMaintenanceBill bill){if(!isOwner(bill,authorization.currentUserId()))throw new AccessDeniedException("You may only pay bills for your own flat");}
 private void requireOwnerPayment(MaintenancePayment payment){if(payment.getPayer()==null||!payment.getPayer().getId().equals(authorization.currentUserId()))throw new AccessDeniedException("You may only verify your own payment");}
 private boolean isOwner(MonthlyMaintenanceBill bill,Long userId){return occupancies.findByResidentUserId(userId).stream().anyMatch(item->Boolean.TRUE.equals(item.getActive())&&item.getOccupancyType()==OccupancyType.OWNER&&item.getResidentRole()==ResidentRole.PRIMARY&&item.getFlat().getId().equals(bill.getFlat().getId()));}
 private User ownerOf(MonthlyMaintenanceBill bill){return occupancies.findByFlatIdAndActiveTrue(bill.getFlat().getId()).stream().filter(item->item.getOccupancyType()==OccupancyType.OWNER&&item.getResidentRole()==ResidentRole.PRIMARY).map(item->item.getResident().getUser()).findFirst().orElseThrow(()->new InvalidRequestException("This flat has no active Flat Owner"));}
 private BigDecimal outstanding(MonthlyMaintenanceBill bill){return bill.getTotalAmount().subtract(bill.getPaidAmount()).max(BigDecimal.ZERO);}
 private MaintenancePayment findOrder(String id){return payments.findByRazorpayOrderId(id).orElseThrow(()->new InvalidRequestException("Razorpay order was not found"));}
 private String createRazorpayOrder(long paise,String receipt){try{String json=mapper.writeValueAsString(Map.of("amount",paise,"currency","INR","receipt",receipt));HttpRequest request=HttpRequest.newBuilder(URI.create("https://api.razorpay.com/v1/orders")).header("Content-Type","application/json").header("Authorization","Basic "+Base64.getEncoder().encodeToString((keyId+":"+keySecret).getBytes(StandardCharsets.UTF_8))).POST(HttpRequest.BodyPublishers.ofString(json)).build();HttpResponse<String> response=HttpClient.newHttpClient().send(request,HttpResponse.BodyHandlers.ofString());if(response.statusCode()/100!=2)throw new InvalidRequestException("Razorpay rejected order creation (HTTP "+response.statusCode()+"). Check that the Test Mode Key ID and Key Secret belong to the same Razorpay account.");String id=mapper.readTree(response.body()).path("id").asText();if(id.isBlank())throw new InvalidRequestException("Razorpay did not return an order id");return id;}catch(InvalidRequestException e){throw e;}catch(Exception e){throw new InvalidRequestException("Unable to contact Razorpay. Check your network connection and Test Mode credentials.");}}
 private MaintenancePaymentResponse response(MaintenancePayment payment){return new MaintenancePaymentResponse(payment.getId(),payment.getSociety().getId(),payment.getAmount(),payment.getPaymentDate(),payment.getPaymentMethod(),payment.getStatus(),payment.getReferenceNumber(),payment.getRazorpayPaymentId(),payment.getNotes(),payment.getCreatedAt(),allocations.findByPaymentId(payment.getId()).stream().map(a->new MaintenancePaymentResponse.Allocation(a.getBill().getId(),a.getBill().getFlat().getFlatNumber(),a.getAmount())).toList());}
 private void requireKeys(){if(keyId.isBlank()||keySecret.isBlank())throw new InvalidRequestException("Razorpay test keys are not configured");}private void requireWebhook(){if(webhookSecret.isBlank())throw new InvalidRequestException("Razorpay webhook secret is not configured");}private String hmac(String value,String secret){try{Mac mac=Mac.getInstance("HmacSHA256");mac.init(new SecretKeySpec(secret.getBytes(StandardCharsets.UTF_8),"HmacSHA256"));return HexFormat.of().formatHex(mac.doFinal(value.getBytes(StandardCharsets.UTF_8)));}catch(Exception e){throw new IllegalStateException(e);}}private boolean constantTime(String a,String b){return java.security.MessageDigest.isEqual(a.getBytes(StandardCharsets.UTF_8),b.getBytes(StandardCharsets.UTF_8));}private String blank(String value){return value==null||value.isBlank()?null:value.trim();}
}
